aa la sameynayaa QR-koodh ammaan ah …</p><button class="retry hidden" id="retry" type="button">Samee koodh cusub</button></section><p class="owner-note">Isticmaalayaasha caadiga ah weli looma furin buundada QR-ka. Dashboard-ka milkiilaha iyo xakamaynta qiimo-dhimista way diyaar yihiin marka gelitaanka la ballaariyo.</p></main><script src="<?= htmlspecialchars(googa_asset_url('assets/vendor/qrcode.bundle.js'), ENT_QUOTES, 'UTF-8') ?>"></script><script>const q=document.querySelector('#qr'),c=document.querySelector('#code'),s=document.querySelector('#status'),start=document.querySelector('#start'),retry=document.querySelector('#retry'),manual=document.querySelector('#manualLink');let pollTimer=0,activeToken='',pollBusy=false;async function api(action,t){const u='api/auth.php?action='+action+(t?'&t='+encodeURIComponent(t):'');const r=await fetch(u,{cache:'no-store',credentials:'same-origin'});return r.json()}function stopPoll(){if(pollTimer){clearTimeout(pollTimer);pollTimer=0}pollBusy=false}function setRetry(show){retry.classList.toggle('hidden',!show);start.disabled=false}function schedulePoll(){stopPoll();pollTimer=window.setTimeout(runPoll,1500)}async function renderQr(url){c.innerHTML='';const canvas=document.createElement('canvas');c.appendChild(canvas);await window.QRCode.toCanvas(canvas,url,{width:280,margin:1})}async function runPoll(){if(!activeToken||pollBusy)return;pollBusy=true;try{const x=await api('poll',activeToken);if(x.state==='approved'){stopPoll();window.location.replace('./');return}if(x.state==='denied'){stopPoll();s.textContent='Gelitaanka waa la diiday. Samee koodh cusub.';setRetry(true);return}if(x.state==='expired'){stopPoll();s.textContent='Koodhku wuu dhacay. Samee mid cusub.';setRetry(true);return}s.textContent=x.state==='scanned'?'Taleefanku wuu furmay. Oggolaansho ayaa la sugayaa …':'Oggolaansho ayaa la sugayaa …';pollBusy=false;schedulePoll()}catch(e){s.textContent='Cillad shabakad ku meel gaar ah ayaa dhacday. QR-koodhku wuu sii muuqanayaa inta aan mar kale isku dayeyno …';pollBusy=false;schedulePoll()}}async function beginQr(){stopPoll();activeToken='';start.disabled=true;setRetry(false);q.classList.remove('hidden');c.innerHTML='';manual.classList.add('hidden');s.textContent='Waxaa la sameynayaa QR-koodh ammaan ah …';try{const d=await api('create');if(!d.token||!d.scanUrl){s.textContent='QR-koodhka lama abuuri karin.';setRetry(true);return}activeToken=d.token;await renderQr(d.scanUrl);manual.href=d.scanUrl;manual.classList.remove('hidden');s.textContent='Oggolaansho ayaa la sugayaa …';pollBusy=false;schedulePoll()}catch(e){s.textContent='QR-gelitaanka lama bilaabi karo hadda.';setRetry(true)}}start.onclick=beginQr;retry.onclick=beginQr;</script></html>
